            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            pts = []
            while q:
                x, y = q.pop()
                pts.append((x, y))
                for a, b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == color and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            out.append((color, pts))
    return out


def canonical(pts):
    coords = [(r-min(x for x,y in pts), c-min(y for x,y in pts)) for r,c in pts]
    variants = []
    for k in range(4):
        cur = coords
        for _ in range(k):
            cur = [(c, -r) for r,c in cur]
